 <section class="screen hidden" id="endScreen"><div class="overlay-card"><div class="eyebrow" id="endEyebrow">Run complete</div><h2 id="endTitle">Wiped out</h2><p id="endCopy">The city always gets one more run.</p><div class="result">DISTANCE FLOWN<strong id="finalDistance">0000 m</strong><span id="finalRings">00 ION RINGS</span></div><div class="card-actions"><button class="primary" id="retryBtn">Fly again <span class="arrow">↗</span></button><button class="secondary" id="homeBtn">Main menu</button></div></div></section>
 <div class="touch-controls" id="touchControls"><div class="touch-pad"><button class="touch-btn touch-up" data-key="up">↑</button><button class="touch-btn touch-left" data-key="left">←</button><button class="touch-btn touch-down" data-key="down">↓</button><button class="touch-btn touch-right" data-key="right">→</button></div><div class="touch-actions"><button class="touch-btn touch-phase" data-key="phase">PHASE</button><button class="touch-btn touch-boost" data-key="boost">BOOST</button></div></div>
 </div>
 <script>
+(()=>{
+const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d',{alpha:false});
+const $=id=>document.getElementById(id);
+const startScreen=$('startScreen'),pauseScreen=$('pauseScreen'),endScreen=$('endScreen'),hud=$('hud');
+let W=0,H=0,DPR=1,now=0,last=0,mode='menu',score=0,rings=0,best=Number(localStorage.getItem('afterburn-best')||0),flux=100,player={x:0,y:-.04},objects=[],particles=[],keys={},spawnClock=0,speed=0.28,boosting=false,phasing=false,shake=0,runTime=0,sceneSeed=17;
+$('menuBest').textContent=String(best).padStart(4,'0');$('best').textContent=String(best).padStart(4,'0');
+function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
+const rand=()=>{sceneSeed=(sceneSeed*16807)%2147483647;return(sceneSeed-1)/2147483646};
+function screenPos(x,y,z){const depth=.13+z*.87;return{x:W*.5+x*W*.39*depth,y:H*.38+(.48-y)*H*.73*depth,scale:.16+depth*1.22}}
+function setScreen(id){[startScreen,pauseScreen,endScreen].forEach(s=>s.classList.toggle('hidden',s.id!==id));hud.classList.toggle('active',mode==='playing'||mode==='paused')}
+function startGame(){mode='playing';score=0;rings=0;flux=100;player={x:0,y:-.04};objects=[];particles=[];spawnClock=.7;speed=.28;runTime=0;shake=0;setScreen('none');$('touchControls').style.display=innerWidth<701?'flex':'';updateHud()}
+function pause(){if(mode!=='playing')return;mode='paused';setScreen('pauseScreen')}
+function resume(){if(mode!=='paused')return;mode='playing';setScreen('none');last=performance.now()}
+function finish(){if(mode!=='playing')return;mode='ended';best=Math.max(best,Math.floor(score));localStorage.setItem('afterburn-best',best);$('menuBest').textContent=String(best).padStart(4,'0');$('best').textContent=String(best).padStart(4,'0');$('finalDistance').textContent=Math.floor(score).toLocaleString()+' m';$('finalRings').textContent=String(rings).padStart(2,'0')+' ION RINGS';$('endEyebrow').textContent=rings>=8?'Beautiful flight':'Run complete';$('endTitle').textContent=score>1600?'Uncatchable':'Wiped out';$('endCopy').textContent=score>1600?'You made the whole district look slow.':'The city always gets one more run.';hud.classList.remove('active');$('touchControls').style.display='none';setScreen('endScreen')}
+$('startBtn').onclick=startGame;$('retryBtn').onclick=startGame;$('resumeBtn').onclick=resume;$('pauseBtn').onclick=pause;$('quitBtn').onclick=()=>{mode='ended';$('touchControls').style.display='none';hud.classList.remove('active');setScreen('endScreen')};$('homeBtn').onclick=()=>{mode='menu';setScreen('startScreen')};
+function updateHud(){$('distance').innerHTML=String(Math.floor(score)).padStart(4,'0')+'<em>M</em>';$('rings').textContent=String(rings).padStart(2,'0');$('fluxText').textContent=Math.round(flux)+'%';$('fluxFill').style.width=flux+'%'}
+const keyMap={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ShiftLeft:'phase',ShiftRight:'phase',Space:'boost'};
+addEventListener('keydown',e=>{const k=keyMap[e.code];if(k){e.preventDefault();keys[k]=true}if(e.code==='Escape'||e.code==='KeyP'){e.preventDefault();mode==='playing'?pause():mode==='paused'?resume():null}if(e.code==='Enter'&&mode==='menu')startGame()});addEventListener('keyup',e=>{const k=keyMap[e.code];if(k)keys[k]=false});
+document.querySelectorAll('.touch-btn').forEach(b=>{const k=b.dataset.key;const on=e=>{e.preventDefault();keys[k]=true;b.classList.add('down')},off=e=>{e.preventDefault();keys[k]=false;b.classList.remove('down')};b.addEventListener('pointerdown',on);['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,off))});
+function spawnWave(){const lane=()=>Math.round((rand()*1.4-.7)*10)/10;const x=lane(),y=-.08+(rand()-.5)*.8;objects.push({kind:'ring',x,y,z:.02,spin:rand()*6.28});if(rand()<.68){let hx=rand()<.5?x+(rand()<.5?-.48:.48):x,hy=hx===x?y+(rand()<.5?-.48:.48):y;hx=Math.max(-.88,Math.min(.88,hx));hy=Math.max(-.65,Math.min(.58,hy));objects.push({kind:rand()<.22?'drone':'mine',x:hx,y:hy,z:.02,phase:rand()*6.28})}if(runTime>22&&rand()<.22){objects.push({kind:'mine',x:Math.max(-.9,Math.min(.9,x+(rand()-.5)*.28)),y:Math.max(-.65,Math.min(.6,y+(rand()-.5)*.3)),z:.02,phase:rand()*6})}}
+function update(dt){if(mode!=='playing')return;runTime+=dt;const ax=(keys.right?1:0)-(keys.left?1:0),ay=(keys.up?1:0)-(keys.down?1:0);player.x=Math.max(-.93,Math.min(.93,player.x+ax*dt*1.28));player.y=Math.max(-.68,Math.min(.63,player.y+ay*dt*1.04));boosting=!!keys.boost;phasing=!!keys.phase&&flux>0;flux=Math.max(0,Math.min(100,flux+(phasing?-34:5.5)*dt));const travel=speed*(boosting?1.6:1)*(1+Math.min(runTime/150,.35));score+=dt*(82*(boosting?1.8:1));spawnClock-=dt;if(spawnClock<=0){spawnWave();spawnClock=Math.max(.56,1.08-runTime*.006)+(rand()-.5)*.18}for(let i=objects.length-1;i>=0;i--){const o=objects[i];o.z+=dt*travel;if(o.kind==='drone')o.x+=Math.sin(runTime*2+o.phase)*dt*.12;if(o.z>.89&&o.z<.96){const d=Math.hypot((o.x-player.x)*.82,(o.y-player.y)*.86);if(o.kind==='ring'&&d<.2){rings++;flux=Math.min(100,flux+23);score+=250;for(let n=0;n<12;n++)particles.push({x:o.x,y:o.y,z:o.z,life:1,color:'#78f3e6',angle:rand()*6.28});objects.splice(i,1);continue}if(o.kind!=='ring'&&d<.2){if(phasing){score+=90;for(let n=0;n<8;n++)particles.push({x:o.x,y:o.y,z:o.z,life:.6,color:'#c77cff',angle:rand()*6.28});objects.splice(i,1);continue}shake=.4;finish();return}}if(o.z>1.08)objects.splice(i,1)}for(let i=particles.length-1;i>=0;i--){particles[i].life-=dt*1.7;if(particles[i].life<=0)particles.splice(i,1)}shake=Math.max(0,shake-dt);updateHud()}

