function updateHud(){$('distance').innerHTML=String(Math.floor(score)).padStart(4,'0')+'<em>M</em>';$('rings').textContent=String(rings).padStart(2,'0');$('fluxText').textContent=Math.round(flux)+'%';$('fluxFill').style.width=flux+'%'}
const skyline=[];for(let i=0;i<70;i++)skyline.push({x:i/70,w:.35+rand()*.9,h:.035+rand()*.25,lit:rand(),tone:rand()});
function drawBackground(){const horizon=H*.38;let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#081522');g.addColorStop(.38,'#183445');g.addColorStop(.62,'#142d39');g.addColorStop(1,'#080f19');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// distant atmospheric glow
let glow=ctx.createRadialGradient(W*.53,horizon,0,W*.53,horizon,Math.max(W,H)*.65);glow.addColorStop(0,'rgba(87,207,204,.19)');glow.addColorStop(.35,'rgba(44,119,145,.09)');glow.addColorStop(1,'rgba(4,10,17,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
// moon / city light source
ctx.save();ctx.globalAlpha=.72;ctx.shadowColor='#a4fff4';ctx.shadowBlur=36;ctx.fillStyle='rgba(194,248,235,.78)';ctx.beginPath();ctx.arc(W*.72,H*.21,Math.min(W,H)*.032,0,Math.PI*2);ctx.fill();ctx.restore();
// distant stars
for(let i=0;i<52;i++){const x=((i*197.3)%W),y=((i*73.9)%Math.max(1,horizon*.88));ctx.fillStyle=`rgba(190,232,231,${.16+.2*(.5+.5*Math.sin(now*.001+i))})`;ctx.fillRect(x,y,1,1)}
// skyline silhouette and lit windows
for(const b of skyline){const x=b.x*W,w=b.w*W/70,hh=b.h*H;ctx.fillStyle=b.tone>.72?'#102735':'#0b1c28';ctx.fillRect(x,horizon-hh,w,hh+3);if(b.tone>.76){ctx.fillStyle='rgba(91,204,205,.27)';ctx.fillRect(x+w*.48,horizon-hh-5,1.2,5)}for(let wy=horizon-hh+8;wy<horizon-6;wy+=10){if(Math.sin(wy*2+b.x*64)>b.lit-.62){ctx.fillStyle=b.tone>.55?'rgba(255,172,119,.35)':'rgba(107,230,224,.29)';ctx.fillRect(x+4+((wy*7)%Math.max(5,w-7)),wy,2,3)}}}
// floating transit lines
ctx.save();ctx.globalAlpha=.26;for(let i=0;i<5;i++){const y=horizon-17-i*26;ctx.strokeStyle=i%2?'#ff9b67':'#75e7df';ctx.lineWidth=i===0?1.5:1;ctx.beginPath();ctx.moveTo(0,y+Math.sin(now*.0005+i)*2);ctx.lineTo(W,y+Math.sin(now*.0005+i+1)*2);ctx.stroke()}ctx.restore();
// perspective flight corridor grid
ctx.save();ctx.lineWidth=1;for(let i=-9;i<=9;i++){const x=W*.5+i*W*.055;ctx.strokeStyle=i%3===0?'rgba(112,222,215,.15)':'rgba(115,183,195,.065)';ctx.beginPath();ctx.moveTo(W*.5+(x-W*.5)*.05,horizon);ctx.lineTo(x*1.35-W*.175,H*1.08);ctx.stroke()}for(let j=0;j<14;j++){const f=(j/14);const y=horizon+(H-horizon)*f*f;ctx.strokeStyle=`rgba(110,220,211,${.018+f*.08})`;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.restore();
// side canyon light pillars
for(let side=0;side<2;side++){const x=side?W*.93:W*.07;const pulse=.45+.35*Math.sin(now*.0018+side);ctx.save();ctx.globalAlpha=pulse;ctx.shadowColor=side?'#ff9c6e':'#64f0df';ctx.shadowBlur=18;const gg=ctx.createLinearGradient(0,horizon-30,0,H);gg.addColorStop(0,'rgba(110,241,222,0)');gg.addColorStop(.35,side?'rgba(255,155,103,.42)':'rgba(105,239,222,.38)');gg.addColorStop(1,'rgba(110,241,222,0)');ctx.fillStyle=gg;ctx.fillRect(x-1,horizon-25,2,H-horizon+30);ctx.restore()}
// luminous horizon line
const hg=ctx.createLinearGradient(0,0,W,0);hg.addColorStop(0,'rgba(120,243,230,0)');hg.addColorStop(.5,'rgba(120,243,230,.38)');hg.addColorStop(1,'rgba(120,243,230,0)');ctx.fillStyle=hg;ctx.fillRect(0,horizon,W,1.5);
}
function drawRing(o){const p=screenPos(o.x,o.y,o.z),r=15*p.scale;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(o.spin+now*.001);ctx.shadowColor='#78f3e6';ctx.shadowBlur=18*p.scale;ctx.strokeStyle='rgba(111,255,231,.95)';ctx.lineWidth=Math.max(1,3*p.scale);ctx.beginPath();ctx.ellipse(0,0,r,r*.75,0,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='rgba(205,255,241,.55)';ctx.lineWidth=Math.max(.7,p.scale);ctx.beginPath();ctx.ellipse(0,0,r*.66,r*.5,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#d9fff4';ctx.beginPath();ctx.arc(0,0,2.4*p.scale,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawHazard(o){const p=screenPos(o.x,o.y,o.z),r=13*p.scale+(o.kind==='drone'?4:0);ctx.save();ctx.translate(p.x,p.y);if(o.kind==='drone'){ctx.rotate(Math.sin(now*.003+o.phase)*.18);ctx.shadowColor='#ff916c';ctx.shadowBlur=20*p.scale;ctx.fillStyle='#301c22';ctx.strokeStyle='#ffae75';ctx.lineWidth=Math.max(1,1.4*p.scale);ctx.beginPath();ctx.moveTo(-r*1.6,0);ctx.lineTo(-r*.45,-r*.55);ctx.lineTo(r*.9,-r*.42);ctx.lineTo(r*1.5,0);ctx.lineTo(r*.8,r*.5);ctx.lineTo(-r*.5,r*.55);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ffd2a1';ctx.fillRect(-r*.2,-r*.12,r*.4,r*.24)}else{ctx.rotate(o.phase+now*.0006);ctx.shadowColor='#ff815f';ctx.shadowBlur=18*p.scale;ctx.strokeStyle='rgba(255,145,104,.82)';ctx.lineWidth=Math.max(1,2*p.scale);ctx.fillStyle='rgba(47,25,30,.8)';ctx.beginPath();ctx.moveTo(0,-r);ctx.lineTo(r*.8,-r*.35);ctx.lineTo(r*.66,r*.65);ctx.lineTo(-r*.1,r);ctx.lineTo(-r*.8,r*.42);ctx.lineTo(-r*.62,-r*.6);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ffaf78';ctx.beginPath();ctx.arc(0,0,2.2*p.scale,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawCar(){const p=screenPos(player.x,player.y,.91),s=Math.min(1.45,Math.max(.78,W/850)),x=p.x,y=p.y;ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.rotate((keys.left?-1:0)+(keys.right?1:0)*.06);const engine=boosting;ctx.globalAlpha=.9;ctx.shadowColor=engine?'#ff9b67':'#63ecdf';ctx.shadowBlur=engine?34:18;const glow=ctx.createRadialGradient(0,10,2,0,12,66);glow.addColorStop(0,engine?'rgba(255,142,91,.56)':'rgba(99,236,223,.36)');glow.addColorStop(1,'rgba(45,180,185,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.ellipse(0,15,54,30,0,0,Math.PI*2);ctx.fill();
// jet trails
for(const side of [-1,1]){ctx.fillStyle=engine?'rgba(255,133,81,.9)':'rgba(91,232,223,.76)';ctx.shadowBlur=15;ctx.beginPath();ctx.moveTo(side*22,29);ctx.lineTo(side*17,44+(Math.random()*5));ctx.lineTo(side*11,29);ctx.fill()}
// wheels
ctx.shadowBlur=0;ctx.fillStyle='#050a10';ctx.beginPath();ctx.roundRect(-37,-6,12,36,5);ctx.roundRect(25,-6,12,36,5);ctx.fill();ctx.fillStyle='#92a9ac';ctx.fillRect(-35,3,3,14);ctx.fillRect(32,3,3,14);
// aerodynamic body
const body=ctx.createLinearGradient(-40,-20,38,28);body.addColorStop(0,'#d7e8e2');body.addColorStop(.28,'#718f90');body.addColorStop(.49,'#263b45');body.addColorStop(.68,'#86aaa5');body.addColorStop(1,'#162a34');ctx.fillStyle=body;ctx.strokeStyle='rgba(218,255,244,.82)';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(0,-39);ctx.quadraticCurveTo(14,-35,24,-14);ctx.lineTo(32,17);ctx.quadraticCurveTo(27,30,0,32);ctx.quadraticCurveTo(-27,30,-32,17);ctx.lineTo(-24,-14);ctx.quadraticCurveTo(-14,-35,0,-39);ctx.closePath();ctx.fill();ctx.stroke();
// windshield and canopy
const glass=ctx.createLinearGradient(0,-30,0,4);glass.addColorStop(0,'#18323e');glass.addColorStop(.5,'#4e8d91');glass.addColorStop(1,'#101e2b');ctx.fillStyle=glass;ctx.beginPath();ctx.moveTo(0,-29);ctx.quadraticCurveTo(13,-26,18,-10);ctx.lineTo(14,3);ctx.quadraticCurveTo(0,8,-14,3);ctx.lineTo(-18,-10);ctx.quadraticCurveTo(-13,-26,0,-29);ctx.fill();ctx.strokeStyle='rgba(202,255,241,.45)';ctx.stroke();ctx.strokeStyle='rgba(180,240,230,.45)';ctx.beginPath();ctx.moveTo(-22,13);ctx.lineTo(22,13);ctx.stroke();
// headlamps & front details
ctx.shadowColor='#bffff2';ctx.shadowBlur=14;ctx.fillStyle='#dffff0';ctx.beginPath();ctx.ellipse(-22,20,6,2.4,-.2,0,Math.PI*2);ctx.ellipse(22,20,6,2.4,.2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='rgba(15,35,42,.8)';ctx.fillRect(-4,20,8,2);ctx.strokeStyle='rgba(238,255,247,.7)';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(0,-36);ctx.lineTo(0,-29);ctx.moveTo(-28,15);ctx.lineTo(-20,17);ctx.moveTo(28,15);ctx.lineTo(20,17);ctx.stroke();ctx.restore();
}

